'use strict';
const docs = <?php echo json_encode($docs, JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT); ?>;
const letters = [
['The name behind the number','A clerk','Our new system calls everyone a “user unit.” I know there is more to a person than a useful record. Where can I begin thinking about human dignity in the light of Christ?','Think of the opening vision of this pontificate: Christ and the human person.'],
['A second chance','A neighbour','My neighbour is convinced that God has finally run out of patience with him. I would like to read about the Father’s mercy with him, without pretending that wrongdoing does not matter.','The title means “Rich in mercy.”'],
['The quiet guest','A confirmation student','We talk a great deal about the Father and the Son. I want to understand the Holy Spirit as more than a symbol on my confirmation card.','Look for the document about the Lord and giver of life.'],
['More than the output','A factory worker','At our factory, people seem to matter only when the output chart goes up. I want to explore the dignity of the worker, not just the value of what we produce.','The person doing the work is at the heart of this document.'],
['What is an economy for?','A town councillor','Our town is arguing about markets, freedom, and the common good. I am looking for a social reflection written a century after Rerum Novarum.','Its anniversary is written into its Latin title.'],
['Nobody disposable','A volunteer','I want a foundation for defending the lives of vulnerable people, from their beginning to their natural end. Which text puts the value of human life at its centre?','The title means “The Gospel of life.”'],
['Beyond our doorstep','A parish volunteer','We have become very good at talking to ourselves. I want to understand why the Church still has a mission to share Christ beyond her own doorstep.','Mission is not a finished chapter in the Church’s story.'],
['Across the street','A Christian friend','Two Christian congregations on our street barely speak. We want to begin praying and talking together seriously, without pretending our differences have vanished.','The title echoes Christ’s prayer “That they may be one.”'],
['A compass for freedom','A philosophy student','My classmates say that a choice becomes right simply because it is freely chosen. I want to understand how conscience, freedom, and moral truth belong together.','Look for the splendour of truth, rather than freedom alone.'],
['Two wings','A curious reader','A friend says faith means putting reason away. I suspect that believing and thinking can help one another in our search for truth. Which document explores this directly?','Its two Latin nouns name the two partners in the question.'],
['An ordinary Tuesday','A lay parishioner','I am not a priest or a member of a religious order. What does my baptism ask of me in the office, in the neighbourhood, and in the Church?','Look for the text specifically addressed to the lay faithful.'],
['Our little household','A parent','Our family wants to understand its Christian vocation. Not just a list of chores, but the responsibilities and gifts of family life itself.','This is an apostolic exhortation focused on the family.'],
['Keeping someone company','A hospital visitor','I do not want to tell a suffering person to “cheer up.” I want to think carefully about suffering in the light of Christ, while continuing to offer practical care.','Look for the letter about the Christian meaning of suffering.'],
['Dignity, not a footnote','A discussion leader','Our reading group wants to consider the dignity and vocation of women in Scripture and the life of the Church. Which letter makes that its central subject?','The title explicitly names the dignity of women.'],
['Before the threshold','An archive researcher','I am studying how the Church prepared spiritually for the Great Jubilee of 2000. I need the letter that looked ahead to it, not the reflection written afterwards.','Written in 1994: the third millennium was still approaching.'],
['After the celebration','A parish planner','The Jubilee year is over in the archive I am reading. What comes next? I want the 2001 call to put out into the deep through holiness, prayer, and communion.','The new millennium has begun, rather than merely approaching.']
];
const $=id=>document.getElementById(id);
function rand(n){const a=new Uint32Array(1),limit=Math.floor(4294967296/n)*n;do{crypto.getRandomValues(a)}while(a[0]>=limit);return a[0]%n}
function shuffle(a){for(let i=a.length-1;i>0;i--){let j=rand(i+1);[a[i],a[j]]=[a[j],a[i]]}return a}
let batch=[], delivered=new Set(), current=0, options={};
function start(){batch=shuffle(docs.map((_,i)=>i)).slice(0,8);delivered=new Set();options={};batch.forEach(id=>options[id]=shuffle([id,...shuffle(docs.map((_,i)=>i).filter(i=>i!==id)).slice(0,3)]));draw();openLetter(0)}
function draw(){$('letters').replaceChildren();batch.forEach((id,i)=>{let b=document.createElement('button');b.type='button';b.className='letter'+(delivered.has(id)?' done':'');b.textContent=delivered.has(id)?'✓ Routed':String(i+1).padStart(2,'0')+' ✉';b.setAttribute('aria-label','Open letter '+(i+1)+(delivered.has(id)?', delivered':''));b.setAttribute('aria-pressed',String(i===current));b.onclick=()=>openLetter(i);$('letters').append(b)});$('fill').style.width=(delivered.size/8*100)+'%';$('count').textContent=delivered.size+' / 8 DELIVERED'}
function openLetter(i){current=i;draw();const id=batch[i], l=letters[id];$('tag').textContent='Letter '+(i+1)+' · From '+l[1];$('title').textContent=l[0];$('message').textContent='“'+l[2]+'”';$('feedback').textContent='';$('instruction').hidden=false;$('choices').hidden=false;$('choices').replaceChildren();$('hint').hidden=delivered.has(id);$('next').hidden=!delivered.has(id);$('again').hidden=true;
options[id].forEach(choice=>{const b=document.createElement('button');b.type='button';b.className='choice';b.textContent=docs[choice][0];const s=document.createElement('span');s.textContent=docs[choice][3];b.append(s);b.onclick=()=>route(choice,b);if(delivered.has(id)){b.disabled=true;if(choice===id)b.classList.add('correct')}$('choices').append(b)});
if(delivered.has(id)){$('feedback').textContent=docs[id][4]+' '+docs[id][2]+', '+docs[id][1]+'.'}
$('note').classList.remove('arrival');void $('note').offsetWidth;$('note').classList.add('arrival')}
function route(choice,button){let id=batch[current];if(delivered.has(id))return;if(choice!==id){button.classList.add('wrong');button.disabled=true;$('feedback').textContent='A nearby shelf, but not the closest fit: '+docs[choice][0]+' focuses on '+docs[choice][3].toLowerCase()+'. Try another destination.';return}delivered.add(id);button.classList.add('correct');$('choices').querySelectorAll('button').forEach(b=>b.disabled=true);$('feedback').textContent='Delivered. '+docs[id][4]+' '+docs[id][2]+', '+docs[id][1]+'.';$('hint').hidden=true;$('next').hidden=false;$('next').textContent=delivered.size===8?'Close today’s postbag →':'Next letter →';draw()}
$('hint').onclick=()=>{$('feedback').textContent=letters[batch[current]][3]};
$('next').onclick=()=>{if(delivered.size<8){for(let k=1;k<=8;k++){const i=(current+k)%8;if(!delivered.has(batch[i])){openLetter(i);return}}}else{$('tag').textContent='The postbag is empty';$('title').textContent='Every letter found a shelf.';$('message').replaceChildren();let seal=document.createElement('div');seal.className='seal';seal.textContent='POSTROOM / COMPLETE';$('message').append(seal);$('message').append(document.createTextNode('Eight small questions, eight places to begin reading. Explore the reference drawer, or open another postbag to meet some different themes.'));$('choices').hidden=true;$('instruction').hidden=true;$('feedback').textContent='';$('next').hidden=true;$('hint').hidden=true;$('again').hidden=false}};
$('again').onclick=start;start();
</script></body></html>
